-- ============================================================
-- 7-Eleven Smart Retail E-Bulletin & Inventory Database Schema
-- COMPLETE 120 SKUs (SKU01 - SKU120) All Items Explicitly Included
-- Added Promo Category field & Bilingual Support (TH / EN)
-- ============================================================

CREATE TABLE IF NOT EXISTS convenience_store_promotions (
    id INT AUTO_INCREMENT PRIMARY KEY,
    product_code VARCHAR(10) NOT NULL UNIQUE,
    name_th VARCHAR(255) NOT NULL,
    name_en VARCHAR(255) NOT NULL,
    category VARCHAR(50) NOT NULL,
    promo_category VARCHAR(50) NOT NULL,
    description_th TEXT,
    description_en TEXT,
    price DECIMAL(10,2) NOT NULL,
    stock_capacity INT DEFAULT 100,
    current_stock INT DEFAULT 0,
    has_promo BOOLEAN DEFAULT TRUE,
    image_url VARCHAR(500)
);

